content:
850              break;
   851          }
   852          first_buf_written += bytes_newly_written;
   853          if ((*bufs)->len == first_buf_written) {
   854              first_buf_written = 0;
   855              ++*bufs;
   856              --*bufcnt;
   857          }
   858      }
   859
   860      return first_buf_written;
   861  }
