   863  size_t flatten_sendvec(h2o_socket_t *sock, h2o_sendvec_t *sendvec)
   864  {
   865      assert(h2o_socket_ssl_buffer_allocator.conf->memsize >= H2O_PULL_SENDVEC_MAX_SIZE);
   866      sock->_write_buf.flattened = h2o_mem_alloc_recycle(&h2o_socket_ssl_buffer_allocator);
   867      size_t len = sendvec->len;
   868
   869      if (!sendvec->callbacks->read_(sendvec, sock->_write_buf.flattened, len)) {
   870          /* failed */
   871          h2o_mem_free_recycle(&h2o_socket_ssl_buffer_allocator, sock->_write_buf.flattened);
   872          sock->_write_buf.flattened = NULL;
   873          return SIZE_MAX;
   874      }
   875      return len;
   876  }
