   896  void h2o_socket_sendvec(h2o_socket_t *sock, h2o_sendvec_t *vecs, size_t cnt, h2o_socket_cb cb)
   897  {
   898      assert(sock->_cb.write == NULL);
   899      assert(sock->_write_buf.flattened == NULL);
   900
   901      sock->_cb.write = cb;
   902
   903      h2o_iovec_t bufs[cnt];
   904      size_t pull_index = SIZE_MAX;
   905
   906      /* copy vectors to bufs, while looking for one to flatten */
   907      for (size_t i = 0; i < cnt; ++i) {
   908          sock->bytes_written += vecs[i].len;
   909          if (vecs[i].callbacks->read_ == h2o_sendvec_read_raw || vecs[i].len == 0) {
   910              bufs[i] = h2o_iovec_init(vecs[i].raw, vecs[i].len);
   911          } else {
   912              assert(pull_index == SIZE_MAX || !"h2o_socket_sendvec can only handle one pull vector at a time");
   913              assert(vecs[i].len <= H2O_PULL_SENDVEC_MAX_SIZE); /* at the moment, this is our size limit */
   914              pull_index = i;
   915          }
   916      }
   917
   918      if (pull_index != SIZE_MAX) {
   919          /* If the pull vector has a send callback, and if we have the necessary conditions to utilize it, Let it write directly to
   920           * the socket. */
   921  #if !H2O_USE_LIBUV
   922          if (pull_index == cnt - 1 && vecs[pull_index].callbacks != NULL &&
   923              do_write_with_sendvec(sock, bufs, cnt - 1, vecs + pull_index))
   924              return;
   925  #endif
   926          /* Load the vector onto memory now. */
   927          size_t pulllen = flatten_sendvec(sock, &vecs[pull_index]);
   928          if (pulllen == SIZE_MAX) {
   929              report_early_write_error(sock);
   930              return;
   931          }
   932          bufs[pull_index] = h2o_iovec_init(sock->_write_buf.flattened, pulllen);
   933      }
   934
   935      do_write(sock, bufs, cnt);
   936  }
