   938  void on_write_complete(h2o_socket_t *sock, const char *err)
   939  {
   940      h2o_socket_cb cb;
   950          return 0;
   951      /* RFC 2616 4.4 states that the following status codes (and response to a HEAD method) should not include message body */
   952      if ((100 <= req->res.status && req->res.status <= 199) || req->res.status == 204 || req->res.status == 304)
   953          return 0;
   954      if (h2o_memis(req->input.method.base, req->input.method.len, H2O_STRLIT("HEAD")))
   955          return 0;
   956
   957      return 1;
