   994  void finalostream_send(h2o_ostream_t *_self, h2o_req_t *_req, h2o_sendvec_t *inbufs, size_t inbufcnt, h2o_send_state_t send_state)
   995  {
   996      struct st_h2o_http1_conn_t *conn = (struct st_h2o_http1_conn_t *)_req->conn;
   997      h2o_sendvec_t bufs[inbufcnt + 1 + 2]; /* 1 for header, 2 for chunked encoding */
   998      size_t bufcnt = 0, chunked_prefix_index = 0;
   999
  1000      assert(&conn->req == _req);
  1001      assert(_self == &conn->_ostr_final.super);
  1002
  1003      if (conn->_ostr_final.informational.write_inflight) {
  1004          conn->_ostr_final.informational.pending_final.inbufs = h2o_mem_alloc_pool(&conn->req.pool, h2o_sendvec_t, inbufcnt);
  1005          memcpy(conn->_ostr_final.informational.pending_final.inbufs, inbufs, sizeof(*inbufs) * inbufcnt);
  1006          conn->_ostr_final.informational.pending_final.inbufcnt = inbufcnt;
  1007          conn->_ostr_final.informational.pending_final.send_state = send_state;
  1008          return;
  1009      }
  1010
  1011      if (send_state == H2O_SEND_STATE_ERROR) {
  1012          conn->req.http1_is_persistent = 0;
  1013          conn->req.send_server_timing = 0;
  1014          if (conn->req.upstream_refused) {
  1015              /* to let the client retry, immediately close the connection without sending any data */
  1016              on_send_complete(conn->sock, NULL);
  1017              return;
  1018          }
  1019      }
  1020
  1021      if (conn->_ostr_final.state == OSTREAM_STATE_HEAD) {
  1022          /* build headers and send */
  1023          conn->req.timestamps.response_start_at = h2o_gettimeofday(conn->super.ctx->loop);
  1024          setup_chunked(&conn->_ostr_final, &conn->req);
  1025          if (conn->req.send_server_timing)
  1026              h2o_add_server_timing_header(&conn->req, conn->_ostr_final.chunked_buf != NULL);
  1027
  1028          const char *connection = conn->req.http1_is_persistent ? "keep-alive" : "close";
  1029          if (conn->req.is_tunnel_req && conn->req.res.status == 101 && conn->req.upgrade.base)
  1030              connection = "upgrade";
  1031          size_t headers_est_size =
  1032              flatten_headers_estimate_size(&conn->req, conn->super.ctx->globalconf->server_name.len + strlen(connection));
  1033          h2o_sendvec_init_raw(bufs + bufcnt, h2o_mem_alloc_pool(&conn->req.pool, char, headers_est_size), 0);
  1034          bufs[bufcnt].len = flatten_headers(bufs[bufcnt].raw, &conn->req, connection);
  1035          ++bufcnt;
  1036          h2o_probe_log_response(&conn->req, conn->_req_index);
  1037          conn->_ostr_final.state = OSTREAM_STATE_BODY;
  1038      }
  1039
  1040      if (conn->_ostr_final.chunked_buf != NULL)
  1041          chunked_prefix_index = bufcnt++;
  1042
  1043      size_t bytes_sent = 0;
  1044      for (size_t i = 0; i != inbufcnt; ++i) {
  1045          bufs[bufcnt++] = inbufs[i];
  1046          bytes_sent += inbufs[i].len;
  1047      }
  1048      conn->req.bytes_sent += bytes_sent;
  1049
  1050      if (conn->_ostr_final.chunked_buf != NULL) {
  1051          encode_chunked(bufs + chunked_prefix_index, bufs + bufcnt, send_state, bytes_sent, conn->req.send_server_timing != 0,
  1052                         conn->_ostr_final.chunked_buf);
  1053          if (bufs[bufcnt].len != 0)
  1054              ++bufcnt;
  1055      }
  1056
  1057      if (bufcnt != 0)
  1058          set_req_io_timeout(conn, conn->super.ctx->globalconf->http1.req_io_timeout, req_io_on_timeout);
  1059
  1060      h2o_socket_sendvec(conn->sock, bufs, bufcnt, h2o_send_state_is_in_progress(send_state) ? on_send_next : on_send_complete);
  1061  }
