   646  void h2o_send_error_generic(h2o_req_t *req, int status, const char *reason, const char *body, int flags)
   647  {
   648      if (req->pathconf == NULL) {
   649          h2o_hostconf_t *hostconf = h2o_req_setup(req);
   650          h2o_req_bind_conf(req, hostconf, &hostconf->fallback_path);
   651      }
   652
   653      /* If the request is broken or incomplete, do not apply filters, as it would be dangerous to do so. Legitimate clients would not
   654       * send broken requests, so we do not need to decorate error responses using errordoc handler or anything else. */
   655      if ((flags & H2O_SEND_ERROR_BROKEN_REQUEST) != 0)
   656          req->_next_filter_index = SIZE_MAX;
   657
   658      if ((flags & H2O_SEND_ERROR_HTTP1_CLOSE_CONNECTION) != 0)
   659          req->http1_is_persistent = 0;
   660
   661      req->res.status = status;
   662      req->res.reason = reason;
   663      req->res.content_length = strlen(body);
   664
   665      if ((flags & H2O_SEND_ERROR_KEEP_HEADERS) == 0)
   666          memset(&req->res.headers, 0, sizeof(req->res.headers));
   667
   668      h2o_add_header(&req->pool, &req->res.headers, H2O_TOKEN_CONTENT_TYPE, NULL, H2O_STRLIT("text/plain; charset=utf-8"));
   669
   670      h2o_send_inline(req, body, SIZE_MAX);
   671  }
